--
-- Name: actualizar_inversion_relaciones(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.actualizar_inversion_relaciones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verificar si ya existe una fila en inversion_relaciones con el mismo ID de veterinario
    IF EXISTS (SELECT 1 FROM inversion_relaciones WHERE id_inversion = NEW."Id_Veterinario") THEN
        -- Actualizar el campo correspondiente en la fila existente
        UPDATE inversion_relaciones
        SET id_dieta = COALESCE(NEW.id_animal, id_dieta),
            id_comida = COALESCE(NEW.id_animal, id_comida)
        WHERE id_inversion = NEW."Id_Veterinario";
    ELSE
        -- Insertar una nueva fila en inversion_relaciones
        INSERT INTO inversion_relaciones (id_inversion, id_veterinario, id_dieta, id_comida)
        VALUES (NEW."Id_Veterinario", NEW.id_animal, NEW.id_animal, NEW.id_animal);
    END IF;

    RETURN NEW;
END;
$$;


